    "label": "CheckRow",
    "html": "<div class=\"measure-frame py-8\"><ul class=\"space-y-2.5 max-w-md\"><li class=\"flex items-start gap-2.5\"><svg viewBox=\"0 0 16 16\" class=\"mt-0.5 h-3.5 w-3.5 flex-shrink-0 text-blueprint/60\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\"><polyline points=\"2,8 6,12 14,4\"></polyline></svg><span class=\"font-sans text-sm leading-snug text-ink/65\">React to a concept in hours, not weeks</span></li><li class=\"flex items-start gap-2.5\"><svg viewBox=\"0 0 16 16\" class=\"mt-0.5 h-3.5 w-3.5 flex-shrink-0 text-blueprint/60\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\"><polyline points=\"2,8 6,12 14,4\"></polyline></svg><span class=\"font-sans text-sm leading-snug text-ink/65\">Hear objections and disagreement, not a satisfaction score</span></li><li class=\"flex items-start gap-2.5\"><svg viewBox=\"0 0 16 16\" class=\"mt-0.5 h-3.5 w-3.5 flex-shrink-0 text-ink/30\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\"><polyline points=\"6,2 10,8 6,14\"></polyline></svg><span class=\"font-sans text-sm leading-snug text-ink/55\">Optional: bring your own avatars</span></li></ul></div>",
