   "": "<div class=\"measure-frame py-8\"><div class=\"max-w-2xl\"><div class=\"rounded-lg border border-line/12 bg-paper-dark/40 overflow-hidden\"><div class=\"flex flex-wrap items-center gap-3 border-b border-line/10 px-3 py-2.5\"><div role=\"group\" class=\"sl-segmented\" aria-label=\"MCP client\"><button type=\"button\" class=\"sl-segmented__item is-active\" aria-pressed=\"true\">Claude Code</button><button type=\"button\" class=\"sl-segmented__item\" aria-pressed=\"false\">Cursor</button><button type=\"button\" class=\"sl-segmented__item\" aria-pressed=\"false\">Codex</button></div><span class=\"sl-eyebrow ml-auto hidden sm:inline text-[10px] text-ink/40\">Set up in under a minute · no API key</span></div><div class=\"flex items-start gap-3 px-4 py-4 sm:px-5 sm:py-5\"><span class=\"mt-0.5 select-none font-mono text-sm text-blueprint\">$</span><pre class=\"flex-1 overflow-x-auto whitespace-pre font-mono text-[13px] leading-relaxed text-ink/80\"><code>claude mcp add sonaloop --scope user --transport http https://api.sonaloop.com/mcp</code></pre><button type=\"button\" class=\"sl-copy flex-shrink-0\" aria-label=\"Copy\"><svg class=\"sl-copy__ico\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><rect x=\"9\" y=\"9\" width=\"11\" height=\"11\" rx=\"2\"></rect><path d=\"M5 15V5a2 2 0 0 1 2-2h10\"></path></svg><svg class=\"sl-copy__check\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M5 13l4 4L19 7\"></path></svg><span class=\"sl-copy__label\">Copy</span></button></div></div></div></div>"
